Hook for memoizing expensive calculations.

```jsx
const expensiveValue = useMemo(() => {
  return computeExpensive(a, b);
}, [a, b]);
```

Hook for memoizing functions.

```jsx
const handleClick = useCallback(() => {
  console.log(count);
}, [count]);
```

Hook for complex state logic using reducer pattern.

```jsx
const [state, dispatch] = useReducer(reducer, initialState);

function reducer(state, action) {
  switch (action.type) {
    case 'increment':
      return { count: state.count + 1 };
    default:
      return state;
  }
}
```

Like useEffect but fires synchronously after DOM mutations, before browser paint.

```jsx
useLayoutEffect(() => {
  // measure DOM, update state
}, []);
```

Component catching JavaScript errors in child component tree.

```jsx
class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  render() {
    if (this.state.hasError) return <h1>Error</h1>;
    return this.props.children;
  }
}
```

Function that takes component and returns enhanced component.

```jsx
function withAuth(Component) {
  return function(props) {
    if (!isAuthenticated) return <Login />;
    return <Component {...props} />;
  };
}
```

Pattern for sharing code using prop whose value is a function.

```jsx
<DataProvider render={data => <Display data={data} />} />

function DataProvider({ render }) {
  const [data, setData] = useState(null);
  return render(data);
}
```

Runtime type checking for props.

```jsx
import PropTypes from 'prop-types';

Button.propTypes = {
  label: PropTypes.string.isRequired,
  onClick: PropTypes.func
};
```

Passes ref through component to child.

```jsx
const Input = React.forwardRef((props, ref) => {
  return <input ref={ref} {...props} />;
});
```

Customizes instance value exposed when using ref.

```jsx
useImperativeHandle(ref, () => ({
  focus: () => inputRef.current.focus()
}));
```

Class component with shallow prop/state comparison.

```jsx
class MyComponent extends React.PureComponent {
  render() {
    return <div>{this.props.value}</div>;
  }
}
```

Reusable function extracting component logic.

```jsx
function useCounter(initial = 0) {
  const [count, setCount] = useState(initial);
  const increment = () => setCount(c => c + 1);
  return { count, increment };
}
```

Hook for programmatic navigation.

```jsx
const navigate = useNavigate();
navigate('/dashboard');
```

Hook for accessing current location object.

```jsx
const location = useLocation();
console.log(location.pathname);
```
